use vstd::prelude::*;

verus! {

fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (result: (Vec<Vec<f32>>, Vec<Vec<f32>>))
    requires
        x.len() > 0,
        y.len() > 0,
    ensures
        let (mx, my) = result;
        mx.len() == y.len(),
        my.len() == y.len(),
        forall|i: usize| i < y.len() ==>
            mx[i].len() == x.len() && my[i].len() == x.len(),
        forall|i: usize, j: usize| i < y.len() && j < x.len() ==>
            mx[i][j] == x[j],
        forall|i: usize, j: usize| i < y.len() && j < x.len() ==>
            my[i][j] == y[i],
{
    let mut mx: Vec<Vec<f32>> = Vec::new();
    let mut my: Vec<Vec<f32>> = Vec::new();
    let mut i: usize = 0;
    // build one row per entry of y
    while i < y.len()
        invariant
            i <= y.len(),
            mx.len() == i,
            my.len() == i,
            // for each completed row k < i, sizes and values are correct
            forall|k: usize| k < i ==>
                mx[k].len() == x.len() &&
                my[k].len() == x.len() &&
                forall|j: usize| j < x.len() ==>
                    mx[k][j] == x[j] &&
                    my[k][j] == y[k],
        decreases y.len() - i,
    {
        let mut row_x: Vec<f32> = Vec::new();
        let mut row_y: Vec<f32> = Vec::new();
        // the constant value to repeat in row_y
        let y_i: f32 = y[i];
        let mut j: usize = 0;
        // build one column per entry of x
        while j < x.len()
            invariant
                j <= x.len(),
                row_x.len() == j,
                row_y.len() == j,
                // for each completed column l < j, row entries are correct
                forall|l: usize| l < j ==>
                    row_x[l] == x[l] &&
                    row_y[l] == y_i,
            decreases x.len() - j,
        {
            row_x.push(x[j]);
            row_y.push(y_i);
            j = j + 1;
        }
        mx.push(row_x);
        my.push(row_y);
        i = i + 1;
    }
    (mx, my)
}

}

